(function(C){C["27a"]=(C["27a"]||[]).concat([{"q": "What is (−1)·v?", "a": "−v, the opposite of v", "w": ["0", "it is not defined", "v"], "why": "Zero-stretch technique: 0·v = 0, t·0 = 0, and (−1)·v = −v."}, {"q": "What must a part W of a space of vectors hold, to be a space itself?", "a": "0, and u + v and t·v whenever it holds u and v", "w": ["at least two vectors", "every vector of length 1", "u + v whenever it holds u and v, and nothing more"], "why": "Inside-space technique."}, {"q": "Do the solutions of y″ = −y + 1 form a space of vectors?", "a": "no: 0 is not one of them, and two solutions add to a solution of y″ = −y + 2", "w": ["yes: solutions can be added", "yes", "no: the statement has no solutions"], "why": "The solutions of y″ = −y do form one."}, {"q": "Is u · v defined in every space of vectors?", "a": "no: the conditions give adding and stretching only; vectors are not multiplied by vectors here", "w": ["yes, when the vectors are lists", "yes", "no: only u × v is"], "why": "A space of vectors is a set with a way to add two members and a way to stretch a member by a real number."}, {"q": "t·v = 0. Is v = 0?", "a": "not when t = 0; it holds when t ≠ 0, by stretching by 1/t", "w": ["only when t = 1", "never", "yes, always"], "why": "Zero-stretch technique: 0·v = 0 for every v."}]);})(window.LADDER_CARDS=window.LADDER_CARDS||{});
(function(C){C["27b"]=(C["27b"]||[]).concat([{"q": "v₁ and v₂ are not parallel in space. Do they build space?", "a": "no: two vectors build at most a plane through 0; space has dimension 3", "w": ["yes, if neither is 0", "yes", "no: they build only a line"], "why": "Same-size technique: every basis of space has 3 vectors."}, {"q": "w₁, …, wₘ build V, and u₁, …, uₖ in V are free. What follows?", "a": "k ≤ m", "w": ["k = m", "k ≥ m", "nothing ties k to m"], "why": "Exchange technique: swap the free vectors in, one at a time, and each time a builder goes out."}, {"q": "Can three vectors in the plane be free?", "a": "no: the plane has dimension 2, so at most two vectors are free", "w": ["yes, if none is 0", "no: no list in the plane is free", "yes, if no two are parallel"], "why": "Exchange technique: a free list is no longer than a list that builds."}, {"q": "Each pair of a list is free. Is the list free?", "a": "not always: (1, 0), (0, 1), (1, 1): every pair is free, the three are not", "w": ["yes, in the plane", "yes", "never"], "why": "Free means that the only mix equal to 0 has every tᵢ = 0."}, {"q": "Has every space of vectors a dimension?", "a": "only those with a finite list that builds them; all polynomials together have none", "w": ["yes", "no: only lists of numbers have", "yes: it is the number of its vectors"], "why": "Same-size technique: if a space has a basis of n vectors, every basis of it has n vectors."}]);})(window.LADDER_CARDS=window.LADDER_CARDS||{});
(function(C){C["27c"]=(C["27c"]||[]).concat([{"q": "Is dim(lost) + dim(reached) = dim W, for a straight map from V to W?", "a": "no: the sum is the dimension of the space you start from, V", "w": ["yes", "no: the sum is dim V + dim W", "no: the sum is 0"], "why": "Lost-plus-reached technique."}, {"q": "L is onto. Is L one-to-one, between any two spaces?", "a": "only when the two dimensions are equal", "w": ["only when L loses a line", "yes", "never"], "why": "If V has the larger dimension, an onto map must lose something."}, {"q": "V has dimension n, and L is straight from V. What adds to n?", "a": "the dimension of what L loses plus the dimension of what it reaches", "w": ["the number of vectors L sends to 0", "the dimensions of V and W", "the dimension of what L reaches plus the dimension of W"], "why": "Lost-plus-reached technique."}, {"q": "L(u) = L(v). Is u = v, for every straight map L?", "a": "only when L loses nothing but 0", "w": ["only when L is onto", "yes, always", "never"], "why": "Nothing-sent technique: L is one-to-one exactly when it loses only 0."}]);})(window.LADDER_CARDS=window.LADDER_CARDS||{});
(function(C){C["27d"]=(C["27d"]||[]).concat([{"q": "Is AB = BA?", "a": "not in general: a quarter turn and a flip disagree, both ways round", "w": ["never", "yes, for square grids", "yes, always"], "why": "AB is doing B and then A."}, {"q": "AB = 0. Is A = 0 or B = 0?", "a": "no: the grid with rows (0, 1), (0, 0) times itself is 0", "w": ["yes", "yes, for square grids", "no: AB is never 0"], "why": "Grids are not a field: a grid other than 0 can lose vectors other than 0."}, {"q": "What is column j of the grid of a straight map L?", "a": "L(eⱼ)", "w": ["L(e₁) + ⋯ + L(eⱼ)", "row j of L", "eⱼ"], "why": "Columns technique."}, {"q": "Is (AB)ᵢⱼ = aᵢⱼbᵢⱼ?", "a": "no: place by place is not doing one after another; it is row i of A against column j of B", "w": ["yes, for square grids", "no: it is aᵢⱼ + bᵢⱼ", "yes"], "why": "Product-is-doing technique: (AB)ᵢⱼ = aᵢ₁b₁ⱼ + ⋯ + aᵢₖbₖⱼ."}]);})(window.LADDER_CARDS=window.LADDER_CARDS||{});
(function(C){C["27e"]=(C["27e"]||[]).concat([{"q": "Is det(tA) = t det A?", "a": "no: each of the n columns is stretched, so det(tA) = tⁿ det A", "w": ["yes", "no: det(tA) = nt det A", "no: det(tA) = det A"], "why": "D is straight in each column."}, {"q": "Does swapping two rows leave det alone?", "a": "no: a row swap also changes the sign", "w": ["no: it makes det 0", "yes: only column swaps change it", "yes"], "why": "27g proves det A equals the det of A turned on its side, so every column technique is a row technique."}, {"q": "det A = 0. Is a column of A all zeros?", "a": "no: a column need only be a mix of the others", "w": ["no: then A = 0", "yes, or a row", "yes"], "why": "Rows (1, 2), (2, 4) have det 0."}]);})(window.LADDER_CARDS=window.LADDER_CARDS||{});
(function(C){C["27f"]=(C["27f"]||[]).concat([{"q": "Are the stretches of A its middle entries?", "a": "only for a grid with 0 on one side of the middle; rows (0, 1), (1, 0) has middle 0, 0 and stretches 1, −1", "w": ["yes, always", "never", "yes, for 2 × 2 grids"], "why": "Stretch-test technique: λ is a stretch exactly when det(A − λI) = 0."}, {"q": "Has every real grid a real stretch?", "a": "no: the quarter turn has stretches i and −i only", "w": ["yes, if it is square", "no: no real grid has", "yes"], "why": "A turn of the plane by a quarter moves every vector off its own line."}, {"q": "Av = λv with v = 0. Does that make λ a stretch of A?", "a": "no: every λ does that with v = 0; the vector must not be 0", "w": ["yes", "no: then λ = 0", "yes, when λ ≠ 0"], "why": "λ is a stretch of A when Av = λv for some vector v other than 0."}, {"q": "Are the stretches of AB products of stretches of A and of B?", "a": "not in general: each vector is only stretched by its own grid", "w": ["yes, for square grids", "no: they are sums", "yes"], "why": "A and B need not share the vectors they only stretch."}, {"q": "A, n × n, has n free vectors that it only stretches. What follows?", "a": "A = PDP⁻¹, with those vectors as the columns of P and their stretches down the middle of D", "w": ["A = D", "A has n different stretches", "A = P + D"], "why": "Straighten-out technique."}]);})(window.LADDER_CARDS=window.LADDER_CARDS||{});
(function(C){C["27g"]=(C["27g"]||[]).concat([{"q": "Is p(A) = det(A − A·I) = 0 a proof that A obeys its stretch polynomial?", "a": "no: a grid is not put in for a number inside a determinant; the stand-in proof is needed", "w": ["yes", "no: A does not obey it", "yes, for 2 × 2 grids"], "why": "Own-polynomial technique: p(A) = c₀I + c₁A + ⋯ + cₙAⁿ is the zero grid."}, {"q": "Is SA = I, for the stand-in grid S?", "a": "no: SA = (det A) I; divide by det A, and only when it is not 0", "w": ["no: SA = 0", "yes", "no: SA = A"], "why": "Stand-in technique: when det A ≠ 0, A⁻¹ = S / det A."}, {"q": "Is the stand-in Cᵢⱼ the det of A with row i and column j struck?", "a": "no: the sign (−1)^(i + j) is part of it", "w": ["yes", "no: strike row j and column i", "no: it is the entry aᵢⱼ"], "why": "Cᵢⱼ is (−1)^(i + j) times that det."}]);})(window.LADDER_CARDS=window.LADDER_CARDS||{});
(function(C){C["27h"]=(C["27h"]||[]).concat([{"q": "B(x, x) = 0. Is x = 0, for every two-slot reading B?", "a": "no: with G having rows (1, 0), (0, −1), B((1, 1), (1, 1)) = 0", "w": ["yes, when G = Gᵀ", "no: B(x, x) is never 0", "yes"], "why": "B(x, y) = xᵀGy, and G need not measure a length."}, {"q": "V has dimension n. What is the dimension of its readings V*?", "a": "n", "w": ["2n", "n²", "1"], "why": "Reading-basis technique: the readings f₁, …, fₙ are a basis of V*."}, {"q": "Does f₁ depend only on v₁?", "a": "no: fᵢ(vⱼ) = 0 for every j ≠ i ties it to the whole basis; change v₂ and f₁ changes", "w": ["yes: f₁(v₁) = 1", "yes", "no: f₁ depends only on v₂"], "why": "Reading-basis technique: fᵢ(vⱼ) = 1 when i = j and 0 otherwise."}, {"q": "Is f(x) = x₁ + 1 a reading?", "a": "no: it sends 0 to 1; a reading is straight", "w": ["yes: it gives a number", "no: a reading gives a vector", "yes"], "why": "A reading sends 0 to 0, as every straight map does."}, {"q": "Is B(x, y) = x₁y₁ straight in the pair (x, y)?", "a": "no: doubling both x and y multiplies it by 4; it is straight in each slot, not in the pair", "w": ["yes", "yes: it is straight in each slot", "no: it is straight in neither slot"], "why": "Two-slot technique: straight in u when v is held, and straight in v when u is held."}]);})(window.LADDER_CARDS=window.LADDER_CARDS||{});
(function(C){C["27i"]=(C["27i"]||[]).concat([{"q": "When is u × v = 0?", "a": "exactly when u and v are not free", "w": ["never", "exactly when u · v = 0", "only when u = 0 or v = 0"], "why": "Cross technique: |u × v| = |u| |v| sin θ."}, {"q": "u · v = 0. Is u = 0 or v = 0?", "a": "no: a dot of 0 means at right angles; (1, 0) · (0, 1) = 0", "w": ["no: then u = v", "yes, in the plane", "yes"], "why": "Angle-between technique: cos θ = u · v/(|u| |v|)."}, {"q": "|r(t)| is the same for every t. What follows?", "a": "r(t) · r′(t) = 0: the vector moves at right angles to itself", "w": ["r′(t) = 0", "r(t) × r′(t) = 0", "|r′(t)| is the same for every t"], "why": "Moving-dot technique: (r · r)′ = 2 r · r′."}, {"q": "Is (u × v) × w = u × (v × w)?", "a": "no: the cross is not grouping-free; (e₁ × e₁) × e₂ = 0, and e₁ × (e₁ × e₂) = −e₂", "w": ["yes", "no: the left side is always 0", "yes, up to sign"], "why": "Cross technique: u × v = 0 exactly when u and v are not free, so e₁ × e₁ = 0."}, {"q": "Is |r(t)|′ = |r′(t)|?", "a": "no: round a circle |r| is fixed, so its slope is 0, while the speed |r′| is not 0", "w": ["no: |r(t)|′ is always 0", "yes", "yes, when r moves in a plane"], "why": "Moving-dot technique: a vector of fixed length moves at right angles to itself."}, {"q": "Is u × v = v × u?", "a": "no: a swap of columns changes the sign of det; v × u = −(u × v)", "w": ["no: v × u = 0", "yes, when u · v = 0", "yes"], "why": "Cross technique."}]);})(window.LADDER_CARDS=window.LADDER_CARDS||{});
(function(C){C["27j"]=(C["27j"]||[]).concat([{"q": "May a stretch of one column be added to another?", "a": "no: columns hold the unknowns; mixing them changes what the unknowns are, and the answers", "w": ["yes", "no: it changes b", "yes: det is unchanged, so the answers are"], "why": "Row-move technique: a row move on [A | b] keeps exactly the same answers x."}, {"q": "What does a row move on [A | b] keep?", "a": "exactly the same answers x", "w": ["the stretches of A", "the entries of b", "the determinant of A"], "why": "Row-move technique."}, {"q": "Have n samenesses in n unknowns exactly one answer?", "a": "only when A can be undone: x + y = 1, 2x + 2y = 2 has a whole line of answers", "w": ["yes, when no entry is 0", "never", "yes"], "why": "Undo-by-rows technique: A can be undone exactly when row moves bring it to I."}, {"q": "May a row be stretched by 0?", "a": "no: it cannot be undone; x + y = 2, x − y = 0 becomes x + y = 2, 0 = 0, with new answers", "w": ["yes", "no: it leaves no answers", "yes: it keeps the answers"], "why": "Row-move technique: each row move is undone by another row move."}, {"q": "A system has more unknowns than samenesses. Has it many answers?", "a": "not always: there may be none; x + y + z = 1, x + y + z = 2", "w": ["yes: a whole line of them", "no: it has exactly one", "yes"], "why": "The lowest terms show a row 0 = 1 when there is no answer."}]);})(window.LADDER_CARDS=window.LADDER_CARDS||{});
(function(C){C["27k"]=(C["27k"]||[]).concat([{"q": "Does the six-term technique, copied to four rows, give det?", "a": "no: its diagonals find 8 terms; a grid of four rows has 4! = 24", "w": ["no: it finds 24 terms where 16 are needed", "yes, with the signs swapped", "yes"], "why": "Use the stair-det technique or the expansion technique."}, {"q": "Is det A = Σⱼ a₁ⱼ det(strike row 1, column j)?", "a": "no: the stand-ins carry the signs (−1)^(1 + j)", "w": ["no: strike column 1 and row j", "yes", "yes, for every row"], "why": "Expansion technique: det A = aᵢ₁Cᵢ₁ + ⋯ + aᵢₙCᵢₙ."}, {"q": "Every entry below the middle of a square grid is 0. What is its det?", "a": "the product of the entries down the middle", "w": ["0", "the sum of the entries down the middle", "the product of all the entries that are not 0"], "why": "Stair-det technique."}, {"q": "Does stretching a row by c leave det alone?", "a": "no: det is straight in that row; it is multiplied by c", "w": ["no: it changes sign", "no: it is multiplied by cⁿ", "yes"], "why": "Only adding a stretch of one row to another leaves det alone."}]);})(window.LADDER_CARDS=window.LADDER_CARDS||{});
(function(C){C["27l"]=(C["27l"]||[]).concat([{"q": "A = PDP⁻¹. Is Aᵏ = PᵏDᵏP⁻ᵏ?", "a": "no: the P⁻¹P in the middle cancel; Aᵏ = PDᵏP⁻¹", "w": ["no: Aᵏ = PᵏDP⁻ᵏ", "yes, when P is undoable", "yes"], "why": "(PDP⁻¹)(PDP⁻¹) = PD²P⁻¹."}, {"q": "Does a repeated stretch mean the grid cannot be straightened out?", "a": "no: I has the stretch 1 twice, and is already straight; what stops a grid is too few vectors", "w": ["no: every grid can be straightened out", "yes", "yes, for 2 × 2 grids"], "why": "A grid is straightened out by n free vectors that it only stretches."}, {"q": "Are the stretches of A + B sums of stretches of A and of B?", "a": "no: rows (0, 1), (0, 0) and rows (0, 0), (1, 0) each have only 0; their sum has 1 and −1", "w": ["yes, for 2 × 2 grids", "no: they are products", "yes"], "why": "A and B need not share the vectors they only stretch."}]);})(window.LADDER_CARDS=window.LADDER_CARDS||{});
(function(C){C["27m"]=(C["27m"]||[]).concat([{"q": "Q and R are turns of space. Is QR = RQ?", "a": "not in general: turns of space do not commute", "w": ["yes: turns of the plane do", "yes", "never"], "why": "Turn-about fails for grids."}, {"q": "det Q = 1. Does Q keep lengths?", "a": "not always: rows (2, 0, 0), (0, ½, 0), (0, 0, 1) have det 1 and double e₁", "w": ["yes, in space", "yes", "no: a length keeper has det −1"], "why": "Length-keeper technique: Q keeps every length exactly when QᵀQ = I."}, {"q": "Q keeps every length. What is Q⁻¹?", "a": "Qᵀ", "w": ["I", "Q", "−Q"], "why": "Length-keeper technique: QᵀQ = I."}, {"q": "Does every turn of the plane keep a vector other than 0 in place?", "a": "no: the axis needs an odd number of directions; a quarter turn of the plane keeps only 0", "w": ["yes: its axis", "yes", "yes: the vector e₁"], "why": "Axis technique: every turn of space keeps some vector u ≠ 0 in place."}]);})(window.LADDER_CARDS=window.LADDER_CARDS||{});
